def authored(
    question_id: str,
    primary: str,
    title: str,
    stem: str,
    correct: str,
    distractors: list[tuple[str, str]],
    rationale: str,
    trap: str,
    secondary: tuple[str, ...] = (),
) -> dict:
    correct_proposition = CORRECT_OPTION_OVERRIDES.get(question_id, correct)
    correct_proposition = correct_proposition[:1].upper() + correct_proposition[1:]
    if correct_proposition[-1:] not in ".!?":
        correct_proposition += "."
    normalized_rationale = rationale[:1].upper() + rationale[1:]
    if normalized_rationale[-1:] not in ".!?":
        normalized_rationale += "."
    options = [correct_proposition] + [text for text, _ in distractors]
    explanations = [
        f"Correct: {normalized_rationale}",
        *[f"Incorrect: {reason}" for _, reason in distractors],
    ]
    return {
        "question_id": question_id,
        "primary_cell": primary,
        "secondary_cells": list(secondary),
        "title": title,
        "stem": stem,
        "options": options,
        "correct_index": 0,
        "correct_proposition": correct_proposition,
        "rationale": normalized_rationale,
        "explanations": explanations,
        "trap": trap,
        "origin": "new",
        "authored_evidence": {
            "tested_operation": stem,
            "required_option_distinction": (
                f"Affirm “{correct_proposition}” while rejecting the three incompatible propositions: "
                + " | ".join(text for text, _ in distractors)
            ),
        },
    }


